package com.corecs.cpu.algorithm;
import com.corecs.cpu.model.*; import java.util.*;
public class SjfAlgorithm implements SchedulingAlgorithm { public SimulationResult simulate(List<ProcessSpec> input,int q){var ps=SchedulingSupport.sorted(input);var out=new ArrayList<GanttSegment>();var ready=new ArrayList<ProcessSpec>();int t=0,i=0;while(i<ps.size()||!ready.isEmpty()){while(i<ps.size()&&ps.get(i).arrivalTime()<=t)ready.add(ps.get(i++));if(ready.isEmpty()){int a=ps.get(i).arrivalTime();out.add(new GanttSegment("IDLE",t,a));t=a;continue;}ready.sort(Comparator.comparingInt(ProcessSpec::burstTime).thenComparingInt(ProcessSpec::arrivalTime).thenComparing(ProcessSpec::id));var p=ready.removeFirst();out.add(new GanttSegment(p.id(),t,t+p.burstTime()));t+=p.burstTime();}return SchedulingSupport.finish(ps,out);} }
